import{_ as e,o as s,c as a,a4 as o}from"./chunks/framework.CQGI5ZO3.js";const E=JSON.parse('{"title":"xs-exit(7)","description":"Inspect final status, retained partials, and original diagnostics.","frontmatter":{"title":"xs-exit(7)","description":"Inspect final status, retained partials, and original diagnostics.","manual":"xs-exit(7)","manualName":"Exit status & errors","sectionNumber":"7"},"headers":[],"relativePath":"exit-status.md","filePath":"exit-status.md"}'),r={name:"exit-status.md"};function n(d,t,i,c,l,p){return s(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="xs-exit-7" tabindex="-1">xs-exit(7) <a class="header-anchor" href="#xs-exit-7" aria-label="Permalink to &quot;xs-exit(7)&quot;">​</a></h1><div class="manual-deck"><strong>Exit status &amp; errors</strong><p>Inspect final status, retained partials, and original diagnostics.</p></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION {#description}&quot;">​</a></h2><p>A final exit status describes the process outcome. Transfer errors include a bounded summary of the first ten diagnostics, grouped by kind, on stderr. Quiet mode keeps errors visible.</p><h2 id="exit-status" tabindex="-1">EXIT STATUS <a class="header-anchor" href="#exit-status" aria-label="Permalink to &quot;EXIT STATUS {#exit-status}&quot;">​</a></h2><div class="manual-table-wrap"><table><thead><tr><th scope="col">Code</th><th scope="col">Meaning</th><th scope="col">Error-summary kind</th></tr></thead><tbody><tr><td><code class="nowrap">0</code></td><td>Successful operation</td><td>—</td></tr><tr><td><code class="nowrap">1</code></td><td>Syntax or usage error</td><td>syntax or usage</td></tr><tr><td><code class="nowrap">2</code></td><td>Protocol incompatibility</td><td>protocol incompatibility</td></tr><tr><td><code class="nowrap">3</code></td><td>Input/output selection error</td><td>file selection</td></tr><tr><td><code class="nowrap">4</code></td><td>Requested action unsupported, including a peer that lacks a requested feature under <code>--no-fallback</code></td><td>unsupported action</td></tr><tr><td><code class="nowrap">5</code></td><td>Failure starting the client/server protocol</td><td>protocol startup</td></tr><tr><td><code class="nowrap">11</code></td><td>File I/O error, including fatal disk-full errors</td><td>file IO</td></tr><tr><td><code class="nowrap">12</code></td><td>Protocol data-stream error, including a remote shell that exits unexpectedly</td><td>stream IO</td></tr><tr><td><code class="nowrap">13</code></td><td>Diagnostic/stdout write failure, including a closed output pipe</td><td>diagnostic IO</td></tr><tr><td><code class="nowrap">14</code></td><td>Interprocess communication error</td><td>IPC</td></tr><tr><td><code class="nowrap">20</code></td><td>SIGINT, SIGTERM, or SIGHUP</td><td>interruption</td></tr><tr><td><code class="nowrap">23</code></td><td>Some files or attributes were not transferred</td><td>partial transfer</td></tr><tr><td><code class="nowrap">24</code></td><td>Source files vanished before transfer</td><td>vanished source files</td></tr><tr><td><code class="nowrap">25</code></td><td>Deletion limit exceeded</td><td>deletion limit</td></tr><tr><td><code class="nowrap">30</code></td><td>Remote idle I/O timeout</td><td>idle timeout</td></tr><tr><td><code class="nowrap">127</code></td><td>Remote helper not found, with fallback disabled, or the remote shell command could not be run</td><td>remote command not found</td></tr><tr><td><code class="nowrap">255</code></td><td>The remote shell itself failed (for example, ssh could not connect); its status is passed through</td><td>remote shell failure</td></tr></tbody></table></div><p>Code <code>124</code> is defined for rsync compatibility but xs does not currently return it.</p><h2 id="missing-source" tabindex="-1">MISSING SOURCE <a class="header-anchor" href="#missing-source" aria-label="Permalink to &quot;MISSING SOURCE {#missing-source}&quot;">​</a></h2><div class="example-caption">Command from the actual error recording</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> ./missing-source/</span><span style="color:#DEDEDE;"> ./unused-backup/</span></span></code></pre></div><div class="captured-doc-output"><span class="micro">ACTUAL XSYNC DIAGNOSTIC / EXIT 23</span><pre><code id="actual-error-output">xs: link_stat &quot;./missing-source/&quot; failed: No such file or directory (2)
xs: error summary: 1 error (showing first 1)
  partial transfer (code 23): 1 error
    link_stat &quot;./missing-source/&quot; failed: No such file or directory (2)
xs error: some files/attrs were not transferred (see previous errors) (code 23)</code></pre></div><h2 id="interruption" tabindex="-1">INTERRUPTION AND RETRY <a class="header-anchor" href="#interruption" aria-label="Permalink to &quot;INTERRUPTION AND RETRY {#interruption}&quot;">​</a></h2><p>Ctrl-C interrupts a run with exit code 20. With <code>-P</code>, completed contiguous partial data can be retained. Rerun the same transfer to verify and reuse matching prefixes.</p><div class="example-caption">Retry a partial transfer</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><p>A completed-byte prefix can be reused only when it matches the source. Transfers do not invoke fallback after an active copy has failed.</p><h2 id="scripts" tabindex="-1">SCRIPT EXAMPLE <a class="header-anchor" href="#scripts" aria-label="Permalink to &quot;SCRIPT EXAMPLE {#scripts}&quot;">​</a></h2><div class="example-caption">Preserve the command’s original exit status</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">if xs </span><span style="color:#DEDEDE;">-a</span><span style="color:#DEDEDE;"> --no-progress</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span><span style="color:#DEDEDE;">; then</span></span>
<span class="line"><span style="color:#DEDEDE;">  echo </span><span style="color:#DEDEDE;">&quot;transfer completed&quot;</span></span>
<span class="line"><span style="color:#DEDEDE;">else</span></span>
<span class="line"><span style="color:#DEDEDE;">  status=$?</span></span>
<span class="line"><span style="color:#DEDEDE;">  echo </span><span style="color:#DEDEDE;">&quot;xs failed with code $status&quot;</span><span style="color:#DEDEDE;"> &gt;&amp;2</span></span>
<span class="line"><span style="color:#DEDEDE;">  exit </span><span style="color:#DEDEDE;">&quot;$status&quot;</span></span>
<span class="line"><span style="color:#DEDEDE;">fi</span></span></code></pre></div><p>An exit-23 result may include successful files and failed files in the same run. Inspect the diagnostics rather than assuming the entire destination was rolled back.</p>`,20)])])}const h=e(r,[["render",n]]);export{E as __pageData,h as default};
